    name: { de: "Naturschutzgebiet Bredhi i Sotirës", hu: "Bredhi i Sotirës Természetvédelmi Terület", ro: "Rezervația Naturală Bredhi i Sotirës", en: "Bredhi i Sotirës Nature Reserve" },
    coords: [20.356, 39.814],
